/**
 * #3365 regression suite: squash-merge containment + shell-injection safety.
 *
 * Builds REAL throwaway git repos rather than mocking git, because both bugs
 * live in what git actually reports, not in our parsing:
 *   - `git cherry` matches patch-ids 1:1, so an N>1 squash reads as unmerged
 *   - `git check-ref-format` rejects spaces but NOT `;`, so a branch can be
 *     named `evil;id` and a shell-interpolated git call executes it
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, rmSync, writeFileSync, appendFileSync, existsSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import {
  git,
  allCommitsSquashMerged,
  unmergedCommitCount,
  contentAlreadyInBase,
  branchIsPushed,
} from '../../../pretool/bash/worktree-merge-verifier.js';

let repo: string;

function run(args: string[], cwd = repo): string {
  return execFileSync('git', args, { cwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
}

beforeAll(() => {
  repo = mkdtempSync(join(tmpdir(), 'ork-3365-'));
  run(['init', '-q', '-b', 'main', '.']);
  run(['config', 'user.email', 't@t.t']);
  run(['config', 'user.name', 't']);
  writeFileSync(join(repo, 'f.txt'), 'base\n');
  run(['add', '.']);
  run(['commit', '-qm', 'base']);

  // N=1 squash-merged branch
  run(['checkout', '-qb', 'one']);
  appendFileSync(join(repo, 'f.txt'), 'one\n');
  run(['commit', '-qam', 'one']);
  run(['checkout', '-q', 'main']);
  run(['merge', '--squash', 'one']);
  run(['commit', '-qm', 'squash one']);

  // N=2 squash-merged branch — the case the shipped guard misses
  run(['checkout', '-qb', 'two']);
  writeFileSync(join(repo, 'g.txt'), 't1\n');
  run(['add', '.']);
  run(['commit', '-qm', 'two-a']);
  appendFileSync(join(repo, 'g.txt'), 't2\n');
  run(['commit', '-qam', 'two-b']);
  run(['checkout', '-q', 'main']);
  run(['merge', '--squash', 'two']);
  run(['commit', '-qm', 'squash two']);

  // genuinely unmerged control
  run(['checkout', '-qb', 'novel']);
  writeFileSync(join(repo, 'h.txt'), 'novel\n');
  run(['add', '.']);
  run(['commit', '-qm', 'novel']);
  run(['checkout', '-q', 'main']);
});

afterAll(() => {
  if (repo) rmSync(repo, { recursive: true, force: true });
});

describe('#3365 squash-merge containment', () => {
  it('N=1 squash: content IS in base', () => {
    expect(contentAlreadyInBase(repo, 'one', 'main')).toBe(true);
  });

  it('N=2 squash: content IS in base — the shipped bug', () => {
    // This is the assertion that fails against the pre-fix implementation.
    expect(contentAlreadyInBase(repo, 'two', 'main')).toBe(true);
  });

  it('genuinely unmerged branch is NOT reported as contained', () => {
    // Guards the fix from being a blanket "always suppress".
    expect(contentAlreadyInBase(repo, 'novel', 'main')).toBe(false);
  });

  it('documents WHY the old predicate was wrong: git cherry misses an N>1 squash', () => {
    // Pinned deliberately. If a future git makes `git cherry` squash-aware,
    // this flips and the union in the hook can be simplified.
    expect(allCommitsSquashMerged(repo, 'one', 'main')).toBe(true);   // N=1 accident
    expect(allCommitsSquashMerged(repo, 'two', 'main')).toBe(false);  // N=2 blind spot
  });

  it('the two predicates are unioned, so N=2 is covered overall', () => {
    const covered =
      contentAlreadyInBase(repo, 'two', 'main') || allCommitsSquashMerged(repo, 'two', 'main');
    expect(covered).toBe(true);
  });
});

describe('#3365 shell-injection safety', () => {
  it('a branch name with shell metacharacters cannot execute', () => {
    // git accepts `;` in a ref name — check-ref-format rejects spaces and a
    // short list of chars, but NOT `;`, backticks, `$(...)` or `|`.
    run(['branch', 'evil;id']);

    // A WEAPONIZED payload, verified 2026-08-13 to be both creatable by git
    // and executable under shell interpolation: ${IFS} supplies the space that
    // check-ref-format forbids literally, so `touch <marker>` really runs.
    const marker = join(repo, 'INJECTED');
    // Written as a template literal with an ESCAPED `\${`, not a plain string:
    // biome's lint/suspicious/noTemplateCurlyInString fires on `${` inside a
    // normal string, and this test's whole subject is a literal ${IFS} payload.
    const payloadBranch = `pwn;touch\${IFS}${marker}`;
    run(['branch', payloadBranch]);

    // IMPORTANT: drive this through helpers that exist in BOTH the pre-fix and
    // post-fix implementations, so this test fails against the OLD code for the
    // RIGHT reason (payload executed) rather than "new export missing".
    // unmergedCommitCount + allCommitsSquashMerged both predate the fix.
    for (const b of ['evil;id', payloadBranch]) {
      unmergedCommitCount(repo, b, 'main');
      allCommitsSquashMerged(repo, b, 'main');
    }
    expect(existsSync(marker)).toBe(false);

    // Then the post-fix-only helpers, for completeness.
    for (const b of ['evil;id', payloadBranch]) {
      contentAlreadyInBase(repo, b, 'main');
      branchIsPushed(repo, b);
    }
    expect(existsSync(marker)).toBe(false);
  });

  it('git() passes a metacharacter branch as ONE argv entry, not shell syntax', () => {
    // Against the old execSync form this returned the sha PLUS the output of
    // `id`. With execFileSync it must fail to resolve a ref literally named
    // "evil;id^{commit}"... which DOES exist here, so assert the shape instead:
    const out = git(repo, ['rev-parse', '--verify', 'evil;id']);
    expect(out).not.toBeNull();
    expect(out).toMatch(/^[0-9a-f]{40}\s*$/); // a bare sha, no command output
    expect(out).not.toMatch(/uid=/);
  });

  it('branchIsPushed is false when there is no remote', () => {
    expect(branchIsPushed(repo, 'one')).toBe(false);
  });
});
